mapper.select:
select r.*,u.user_name as userName,g.game_name as gameName,
(select count(*) from room_user ru where ru.room_id=r.room_id and ru.status=1) as counts
from room r
left join tb_user u on u.user_id=r.user_id
left join game g on g.id=r.game_id
where 1=1

    and u.user_id=#{userId}


    and r.room_no=#{roomNo}


    and r.room_name like concat('%',#{roomName},'%')


    and u.user_name like concat('%',#{userName},'%')


    and r.status = #{status}


    and r.game_id = #{gameId}


    and r.room_type = #{roomType}


    and (r.room_name like concat('%',#{search},'%') or r.room_no like concat('%',#{search},'%') or u.user_name like concat('%',#{search},'%'))

order by r.create_time desc
